// ============================================================================
// FreeLang Query 모듈 - SQL-like 쿼리 실행 엔진
// ============================================================================
// 목표: schema.fl 기반 테이블에서 WHERE/ORDER BY/LIMIT/집계 쿼리 실행
// 원리:
//   1. WhereClause: 컬럼 인덱스 + 연산자 + 비교값
//   2. query_execute: 전체 행 순회 → 조건 평가 → 정렬 → 페이징
//   3. 집계: COUNT/SUM/MAX
// 구조:
//   - 상수 정의 (연산자, 집계 타입)
//   - WhereClause, OrderBy, Query, QueryResult 구조체
//   - 쿼리 빌더 함수 (체이닝 스타일)
//   - query_execute 실행 엔진
// ============================================================================

module query {
    // === 비교 연산자 ===
    const OP_EQ:   i32 = 1;   // ==
    const OP_NE:   i32 = 2;   // !=
    const OP_GT:   i32 = 3;   // >
    const OP_LT:   i32 = 4;   // <
    const OP_GE:   i32 = 5;   // >=
    const OP_LE:   i32 = 6;   // <=
    const OP_LIKE: i32 = 7;   // 접두어 일치 (str_starts_with)

    // === 집계 타입 ===
    const AGG_NONE:  i32 = 0;
    const AGG_COUNT: i32 = 1;
    const AGG_SUM:   i32 = 2;
    const AGG_MAX:   i32 = 3;
    const AGG_MIN:   i32 = 4;

    // === 제한값 ===
    const MAX_WHERE: i32 = 8;
    const MAX_RESULT_ROWS: i32 = 1024;

    // === 에러 코드 ===
    const QUERY_OK:         i32 = 0;
    const QUERY_ERR_TABLE:  i32 = 10;
    const QUERY_ERR_COL:    i32 = 11;
    const QUERY_ERR_EMPTY:  i32 = 12;

    // === 데이터 구조체 ===

    struct WhereClause {
        col_idx:  i32;
        op:       i32;
        int_val:  i64;
        str_val:  string;
        is_str:   bool;   // true이면 str_val 사용, false이면 int_val 사용
    }

    struct OrderBy {
        col_idx: i32;
        asc:     bool;
        is_str:  bool;   // 문자열 정렬 여부
    }

    struct Query {
        // 대상 테이블 (포인터 대신 복사 — FreeLang 제약)
        table_ptr:   i32;      // 전역 테이블 인덱스 (간단화)
        wheres:      [WhereClause];
        where_count: i32;
        order_by:    OrderBy;
        has_order:   bool;
        limit:       i32;
        offset:      i32;
        agg_type:    i32;
        agg_col:     i32;
    }

    struct QueryResult {
        // 결과 행 인덱스 (schema.Table의 row_idx)
        row_indices: [i32];
        row_count:   i32;
        agg_value:   i64;
        error_code:  i32;
    }

    // === 쿼리 실행 (핵심) ===
    // schema.Table을 직접 받아서 처리

    func query_table(t: schema.Table) -> Query {
        return Query{
            table_ptr:   0,
            wheres:      make([WhereClause], MAX_WHERE),
            where_count: 0,
            order_by:    OrderBy{ col_idx: 0, asc: true, is_str: false },
            has_order:   false,
            limit:       MAX_RESULT_ROWS,
            offset:      0,
            agg_type:    AGG_NONE,
            agg_col:     0,
        };
    }

    // WHERE int 조건 추가
    func (q: *Query) where_int(col_idx: i32, op: i32, val: i64) -> bool {
        if q.where_count >= MAX_WHERE {
            return false;
        }
        q.wheres[q.where_count] = WhereClause{
            col_idx: col_idx,
            op:      op,
            int_val: val,
            str_val: "",
            is_str:  false,
        };
        q.where_count = q.where_count + 1;
        return true;
    }

    // WHERE str 조건 추가
    func (q: *Query) where_str(col_idx: i32, op: i32, val: string) -> bool {
        if q.where_count >= MAX_WHERE {
            return false;
        }
        q.wheres[q.where_count] = WhereClause{
            col_idx: col_idx,
            op:      op,
            int_val: 0,
            str_val: val,
            is_str:  true,
        };
        q.where_count = q.where_count + 1;
        return true;
    }

    // ORDER BY 설정
    func (q: *Query) order_by_int(col_idx: i32, asc: bool) {
        q.order_by = OrderBy{ col_idx: col_idx, asc: asc, is_str: false };
        q.has_order = true;
    }

    func (q: *Query) order_by_str(col_idx: i32, asc: bool) {
        q.order_by = OrderBy{ col_idx: col_idx, asc: asc, is_str: true };
        q.has_order = true;
    }

    // LIMIT/OFFSET 설정
    func (q: *Query) set_limit(limit: i32) {
        q.limit = limit;
    }

    func (q: *Query) set_offset(offset: i32) {
        q.offset = offset;
    }

    // 집계 설정
    func (q: *Query) set_aggregate(agg_type: i32, col_idx: i32) {
        q.agg_type = agg_type;
        q.agg_col = col_idx;
    }

    // === 조건 평가 함수 ===

    @inline
    func eval_int_op(actual: i64, op: i32, expected: i64) -> bool {
        if op == OP_EQ  { return actual == expected; }
        if op == OP_NE  { return actual != expected; }
        if op == OP_GT  { return actual > expected; }
        if op == OP_LT  { return actual < expected; }
        if op == OP_GE  { return actual >= expected; }
        if op == OP_LE  { return actual <= expected; }
        return false;
    }

    @inline
    func eval_str_op(actual: string, op: i32, expected: string) -> bool {
        if op == OP_EQ   { return actual == expected; }
        if op == OP_NE   { return actual != expected; }
        if op == OP_LIKE {
            // 접두어 일치 (str_starts_with 시뮬레이션)
            let exp_len = len(expected);
            let act_len = len(actual);
            if exp_len > act_len {
                return false;
            }
            let i = 0;
            for i = 0; i < exp_len; i = i + 1 {
                if char_at(actual, i) != char_at(expected, i) {
                    return false;
                }
            }
            return true;
        }
        return false;
    }

    // WHERE 절 평가 (AND 연결)
    func eval_where(t: schema.Table, row_idx: i32, wheres: [WhereClause], where_count: i32) -> bool {
        let i = 0;
        for i = 0; i < where_count; i = i + 1 {
            let w = wheres[i];
            let col_idx = w.col_idx;
            if col_idx < 0 || col_idx >= t.schema.col_count {
                return false;
            }
            let col_type = t.schema.col_defs[col_idx].col_type;

            if col_type == schema.COL_TYPE_INT {
                let actual = t.get_int_val(row_idx, col_idx);
                if !eval_int_op(actual, w.op, w.int_val) {
                    return false;
                }
            } else if col_type == schema.COL_TYPE_STR {
                let actual = t.get_str_val(row_idx, col_idx);
                if !eval_str_op(actual, w.op, w.str_val) {
                    return false;
                }
            } else if col_type == schema.COL_TYPE_BOOL {
                let actual_bool = t.get_bool_val(row_idx, col_idx);
                let actual_i64 = if actual_bool { 1 } else { 0 };
                if !eval_int_op(actual_i64, w.op, w.int_val) {
                    return false;
                }
            }
        }
        return true;
    }

    // === 정렬 (삽입 정렬) ===

    func sort_by_int(t: schema.Table, indices: [i32], count: i32, col_idx: i32, asc: bool) {
        let i = 1;
        for i = 1; i < count; i = i + 1 {
            let key_idx = indices[i];
            let key_val = t.get_int_val(key_idx, col_idx);
            let j = i - 1;

            for j >= 0 {
                let cmp_val = t.get_int_val(indices[j], col_idx);
                let should_swap = if asc { cmp_val > key_val } else { cmp_val < key_val };
                if !should_swap {
                    break;
                }
                indices[j + 1] = indices[j];
                j = j - 1;
            }
            indices[j + 1] = key_idx;
        }
    }

    func sort_by_str(t: schema.Table, indices: [i32], count: i32, col_idx: i32, asc: bool) {
        let i = 1;
        for i = 1; i < count; i = i + 1 {
            let key_idx = indices[i];
            let key_val = t.get_str_val(key_idx, col_idx);
            let j = i - 1;

            for j >= 0 {
                let cmp_val = t.get_str_val(indices[j], col_idx);
                // 문자열 비교: 첫 글자만 (간단화)
                let should_swap = false;
                if len(cmp_val) > 0 && len(key_val) > 0 {
                    if asc {
                        should_swap = char_at(cmp_val, 0) > char_at(key_val, 0);
                    } else {
                        should_swap = char_at(cmp_val, 0) < char_at(key_val, 0);
                    }
                } else if asc {
                    should_swap = len(cmp_val) > len(key_val);
                }
                if !should_swap {
                    break;
                }
                indices[j + 1] = indices[j];
                j = j - 1;
            }
            indices[j + 1] = key_idx;
        }
    }

    // === 쿼리 실행 ===

    func execute(t: schema.Table, q: Query) -> QueryResult {
        let result = QueryResult{
            row_indices: make([i32], MAX_RESULT_ROWS),
            row_count:   0,
            agg_value:   0,
            error_code:  QUERY_OK,
        };

        // 1단계: WHERE 필터링
        let candidates = make([i32], MAX_RESULT_ROWS);
        let candidate_count = 0;
        let i = 0;
        for i = 0; i < t.row_count; i = i + 1 {
            if !t.is_alive(i) {
                continue;
            }
            if eval_where(t, i, q.wheres, q.where_count) {
                if candidate_count < MAX_RESULT_ROWS {
                    candidates[candidate_count] = i;
                    candidate_count = candidate_count + 1;
                }
            }
        }

        // 2단계: 정렬 (ORDER BY)
        if q.has_order {
            if q.order_by.is_str {
                sort_by_str(t, candidates, candidate_count, q.order_by.col_idx, q.order_by.asc);
            } else {
                sort_by_int(t, candidates, candidate_count, q.order_by.col_idx, q.order_by.asc);
            }
        }

        // 3단계: OFFSET + LIMIT 적용
        let start = q.offset;
        let end = start + q.limit;
        if end > candidate_count {
            end = candidate_count;
        }

        for i = start; i < end; i = i + 1 {
            result.row_indices[result.row_count] = candidates[i];
            result.row_count = result.row_count + 1;
        }

        // 4단계: 집계
        if q.agg_type == AGG_COUNT {
            result.agg_value = i64(candidate_count);
        } else if q.agg_type == AGG_SUM {
            let sum: i64 = 0;
            for i = 0; i < candidate_count; i = i + 1 {
                sum = sum + t.get_int_val(candidates[i], q.agg_col);
            }
            result.agg_value = sum;
        } else if q.agg_type == AGG_MAX {
            if candidate_count > 0 {
                let max_val = t.get_int_val(candidates[0], q.agg_col);
                for i = 1; i < candidate_count; i = i + 1 {
                    let v = t.get_int_val(candidates[i], q.agg_col);
                    if v > max_val {
                        max_val = v;
                    }
                }
                result.agg_value = max_val;
            }
        } else if q.agg_type == AGG_MIN {
            if candidate_count > 0 {
                let min_val = t.get_int_val(candidates[0], q.agg_col);
                for i = 1; i < candidate_count; i = i + 1 {
                    let v = t.get_int_val(candidates[i], q.agg_col);
                    if v < min_val {
                        min_val = v;
                    }
                }
                result.agg_value = min_val;
            }
        }

        return result;
    }

    // === 헬퍼 ===

    func result_row_count(r: QueryResult) -> i32 {
        return r.row_count;
    }

    func result_agg(r: QueryResult) -> i64 {
        return r.agg_value;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

// === 사용 시나리오 (주석) ===
//
// 기본 쿼리:
//   let q = query.query_table(t);
//   q.where_int(0, query.OP_GT, 10);     // col[0] > 10
//   q.where_str(1, query.OP_EQ, "Alice"); // col[1] == "Alice"
//   q.order_by_int(0, false);             // ORDER BY col[0] DESC
//   q.set_limit(10);
//   q.set_offset(0);
//   let result = query.execute(t, q);
//
// 집계:
//   let q2 = query.query_table(t);
//   q2.set_aggregate(query.AGG_COUNT, 0);
//   let r = query.execute(t, q2);
//   print("count = " + i64_to_str(r.agg_value));
//
// LIKE 검색:
//   q.where_str(1, query.OP_LIKE, "Ali"); // "Alice", "Alicia" 등 매칭
//
